export type BrandKey = keyof typeof brandMarks;

export const BrandIcon = ({
  name,
  className = "",
  size,
}: {
  name: string;
  className?: string;
  size?: number;
}) => {
  const mark = brandMarks[name];
  if (!mark) return null;
  return (
    <svg
      role="img"
      viewBox="0 0 24 24"
      width={size}
      height={size}
      className={className}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
    >
      <title>{mark.title}</title>
      <path d={mark.d} />
    </svg>
  );
};
